a = [0] * N
def main():
    n, k = map(int, input().split())
    aa = input().split()
    for i in range(1, n + 1):
        a[i] = int(aa[i-1])
    a[1:n + 1] = sorted(a[1:n + 1])
    ans = 0
    for i in range(1, n + 1):
        sum = 0
        for j in range(i, 0, -1):
            if a[i] - a[j] <= k:
                sum += a[j]
            else:
                break
        ans = max(ans, sum)
    print(ans)
if __name__ == "__main__":
    main()
